4: describe('input/context proper narrowing in procedure chain', () => {
5:   test("a narrower input type earlier in the chain should not widen because of a later middleware's wider input requirements", () => {
6:     const t = initTRPC.create();
7: 
8:     const organizationAuth = experimental_standaloneMiddleware<{
9:       input: { organizationId?: string };
10:     }>().create(async ({ next, ctx }) => {
11:       return await next({ ctx });
12:     });
13: 
14:     t.router({
15:       createProject: t.procedure
16:         // input enforces that organizationId is required
17:         .input(z.object({ organizationId: z.string().uuid() }))
18:         // middleware allows organizationId to be optional
19:         .use(organizationAuth)
20:         .mutation(({ input }) => {
21:           // input is still required
22:           expectTypeOf(input).toEqualTypeOf<{ organizationId: string }>();
23:         }),
24:       updateProject: t.procedure
25:         // input allows organizationId to be optional
26:         .input(z.object({ organizationId: z.string().uuid().optional() }))
27:         // middleware allows organizationId to be optional
28:         .use(organizationAuth)
29:         .mutation(({ input }) => {
30:           // input remains optional
31:           expectTypeOf(input).toEqualTypeOf<{ organizationId?: string }>();
32:         }),
36:   test("a narrower ctx type earlier in the chain should not widen because of a later middleware's wider ctx requirements", () => {
37:     const t = initTRPC.context<{ organizationId: string }>().create();
38: 
39:     const organizationCtx = experimental_standaloneMiddleware<{
40:       ctx: { organizationId?: string };
41:     }>().create(async ({ next }) => {
42:       return next();
43:     });
44: 
45:     t.router({
46:       createProject: t.procedure.use(organizationCtx).mutation((opts) => {
47:         expectTypeOf(opts.ctx).toEqualTypeOf<{ organizationId: string }>();
48:       }),
49:     });
50:   });
51: });

